(6147470, 906784, 119404, '<td valign="top">could have gone a little closer to the scene..</td>', 'could have gone a little closer to the scene..', '2010-09-01 01:11:30.000000', NULL, 1),
(6147472, 905597, 19035, '<td valign="top">I am a fellow Clevelander.</td>', 'I am a fellow Clevelander.', '2010-09-01 01:11:52.000000', NULL, 1),
(6147615, 906019, 33361, '<td valign="top">Wow! A great image for the challenge.</td>', 'Wow! A great image for the challenge.', '2010-09-01 01:45:42.000000', NULL, 1),
(6147642, 906423, 83313, '<td valign="top">Interesting choice of shorts and boots...</td>', 'Interesting choice of shorts and boots...', '2010-09-01 01:54:45.000000', NULL, 1),
(6147646, 905635, 83313, '<td valign="top">I like this, but how is this photojournalism? I''m trying and just not how it suits. Perhaps you needed to shoehorn that connection into the title.</td>', 'I like this, but how is this photojournalism? I''m trying and just not how it suits. Perhaps you needed to shoehorn that connection into the title.', '2010-09-01 01:57:23.000000', NULL, 1),
