(6147686, 906449, 103032, '<td valign="top">Nice capture of the kid looking up surrounded by the other contestants.  Would be fitting in a metro or living section of a paper.</td>', 'Nice capture of the kid looking up surrounded by the other contestants.  Would be fitting in a metro or living section of a paper.', '2010-09-01 02:25:16.000000', NULL, 1),
