(6147911, 906634, 28742, '<td valign="top">Are you sure they''re not looking for homeless folks up there? ;-)</td>', 'Are you sure they''re not looking for homeless folks up there? ;-)', '2010-09-01 05:42:00.000000', NULL, 1),
(6147912, 906449, 28742, '<td valign="top">Until they all die from brain freeze. :P</td>', 'Until they all die from brain freeze. :P', '2010-09-01 05:42:26.000000', NULL, 1),
