(6147925, 906677, 28742, '<td valign="top">not that close. the runner needs a lecture on stretching for the base - not curling up like a potato bug. ;-)</td>', 'not that close. the runner needs a lecture on stretching for the base - not curling up like a potato bug. ;-)', '2010-09-01 05:54:40.000000', NULL, 1),
(6147984, 906029, 113278, '<td valign="top">Would have been nice to have captured the bear in the shot. Still pretty well done.</td>', 'Would have been nice to have captured the bear in the shot. Still pretty well done.', '2010-09-01 08:10:03.000000', NULL, 1),
(6147987, 906873, 37845, '<td valign="top">GO JAYS GO!!!</td>', 'GO JAYS GO!!!', '2010-09-01 08:11:32.000000', NULL, 1),
(6148001, 906188, 23394, '<td valign="top">possibly could be used as a feature piece, but needs to be cropped tighter.  the best pj photos don''t need captioning, but the women with her back turned distracts from the story (as we can''t tell what she''s doing).</td>', 'possibly could be used as a feature piece, but needs to be cropped tighter.  the best pj photos don''t need captioning, but the women with her back turned distracts from the story (as we can''t tell what she''s doing).', '2010-09-01 08:32:40.000000', NULL, 1),
(6148003, 906749, 23394, '<td valign="top">nice shot, nice perspective, nice exposure.  good work!</td>', 'nice shot, nice perspective, nice exposure.  good work!', '2010-09-01 08:33:27.000000', NULL, 1),
(6148005, 905784, 23394, '<td valign="top">tough shot, well done.  if anything, i would have looked for a perspective that didn''t include the light pole.</td>', 'tough shot, well done.  if anything, i would have looked for a perspective that didn''t include the light pole.', '2010-09-01 08:34:59.000000', NULL, 1),
(6148008, 906343, 23394, '<td valign="top">interesting, but not in a pj way.  without a caption, there is not story to this photo...nothing to tell who-what-when-where-why.</td>', 'interesting, but not in a pj way.  without a caption, there is not story to this photo...nothing to tell who-what-when-where-why.', '2010-09-01 08:36:20.000000', NULL, 1),
(6148010, 906567, 23394, '<td valign="top">nice idea for a feature photo, but needs more light (tripod and longer shutter).</td>', 'nice idea for a feature photo, but needs more light (tripod and longer shutter).', '2010-09-01 08:37:27.000000', NULL, 1),
(6148012, 906822, 23394, '<td valign="top">nice try, but should properly be hammered in the scoring for dnmc ;-)</td>', 'nice try, but should properly be hammered in the scoring for dnmc ;-)', '2010-09-01 08:38:06.000000', NULL, 1),
(6148013, 906158, 23394, '<td valign="top">nice environmental portrait.  the coins, though, speak more to a set up shot than a possibly found shot.  in pj, the rule is about telling the story, not making the story...</td>', 'nice environmental portrait.  the coins, though, speak more to a set up shot than a possibly found shot.  in pj, the rule is about telling the story, not making the story...', '2010-09-01 08:39:28.000000', NULL, 1),
(6148014, 906330, 23394, '<td valign="top">dnmc, at least from a pj standpoint.  maybe for an advertising challenge, but not pj.</td>', 'dnmc, at least from a pj standpoint.  maybe for an advertising challenge, but not pj.', '2010-09-01 08:40:50.000000', NULL, 1),
(6148015, 906722, 23394, '<td valign="top">nice shoehorn.  my newspaper doesn''t cover weddings :P</td>', 'nice shoehorn.  my newspaper doesn''t cover weddings :P', '2010-09-01 08:45:49.000000', NULL, 1),
(6148016, 905572, 23394, '<td valign="top">nothin but a snapshot.  no who-what-when-where-why story coming through at all...</td>', 'nothin but a snapshot.  no who-what-when-where-why story coming through at all...', '2010-09-01 08:46:32.000000', NULL, 1),
(6148018, 906529, 23394, '<td valign="top">nice grab!</td>', 'nice grab!', '2010-09-01 08:50:39.000000', NULL, 1),
(6148019, 906881, 23394, '<td valign="top">cute shoehorn, but there are no who-what-when-where-why elements to tell a news story...</td>', 'cute shoehorn, but there are no who-what-when-where-why elements to tell a news story...', '2010-09-01 08:51:28.000000', NULL, 1),
(6148024, 905597, 23394, '<td valign="top">the best pj shots need no captioning as the images tell their own story.  as is, there are no story-telling elements here...</td>', 'the best pj shots need no captioning as the images tell their own story.  as is, there are no story-telling elements here...', '2010-09-01 08:53:28.000000', NULL, 1),
(6148025, 906699, 117804, '<td valign="top">Nice journalistic shot. I would have focused more on the governor, the flag and the security words... with a title like Governor speech on National security :-)</td>', 'Nice journalistic shot. I would have focused more on the governor, the flag and the security words... with a title like Governor speech on National security :-)', '2010-09-01 08:54:05.000000', NULL, 1),
(6148029, 906611, 23394, '<td valign="top">nice enough environmental portrait, but without any other story-telling elements, it won''t stand on its own.</td>', 'nice enough environmental portrait, but without any other story-telling elements, it won''t stand on its own.', '2010-09-01 08:55:21.000000', NULL, 1),
(6148030, 906706, 117804, '<td valign="top">at last something funny in the challenge ;-)</td>', 'at last something funny in the challenge ;-)', '2010-09-01 08:55:34.000000', NULL, 1),
(6148032, 906873, 23394, '<td valign="top">needs to be cropped a LOT LOT tighter.  in pj, you really want to fill the frame, removing all but necessary story telling elements.</td>', 'needs to be cropped a LOT LOT tighter.  in pj, you really want to fill the frame, removing all but necessary story telling elements.', '2010-09-01 08:57:00.000000', NULL, 1),
(6148034, 905576, 117804, '<td valign="top">Perhaps a little bit too dark...</td>', 'Perhaps a little bit too dark...', '2010-09-01 08:57:40.000000', NULL, 1),
(6148036, 906884, 23394, '<td valign="top">nice enough featurish image, but there are a lot of other perspectives that would have given this a more dynamic feel.  as is, it''s a snapshot.</td>', 'nice enough featurish image, but there are a lot of other perspectives that would have given this a more dynamic feel.  as is, it''s a snapshot.', '2010-09-01 08:58:22.000000', NULL, 1),
(6148038, 906607, 117804, '<td valign="top">funny, I like the title</td>', 'funny, I like the title', '2010-09-01 09:00:03.000000', NULL, 1),
(6148039, 906449, 23394, '<td valign="top">nice work.  i''d be inclined to put the camera on the table pointing up into one kid''s face, clicking through the all the facial expressions close up.  all the same, your image tells a story without a need for a caption.</td>', 'nice work.  i''d be inclined to put the camera on the table pointing up into one kid''s face, clicking through the all the facial expressions close up.  all the same, your image tells a story without a need for a caption.', '2010-09-01 09:00:31.000000', NULL, 1),
(6148041, 906028, 117804, '<td valign="top">strangely realistic... could have it from a journal in Haiti...</td>', 'strangely realistic... could have it from a journal in Haiti...', '2010-09-01 09:01:33.000000', NULL, 1),
(6148044, 906452, 23394, '<td valign="top">ok, there''s something going on here, but can''t tell what.  without any more visual clues, the image relies on a caption.  the best pj images tell their own story...</td>', 'ok, there''s something going on here, but can''t tell what.  without any more visual clues, the image relies on a caption.  the best pj images tell their own story...', '2010-09-01 09:02:18.000000', NULL, 1),
