(6148052, 906647, 23394, '<td valign="top">too bad about those trees.  not quite sure how ''newsworthy'' this image is, but there''s probably a place for it.</td>', 'too bad about those trees.  not quite sure how ''newsworthy'' this image is, but there''s probably a place for it.', '2010-09-01 09:05:22.000000', NULL, 1),
(6148053, 906634, 23394, '<td valign="top">not bad.</td>', 'not bad.', '2010-09-01 09:06:08.000000', NULL, 1),
(6148054, 905582, 23394, '<td valign="top">better luck next time...</td>', 'better luck next time...', '2010-09-01 09:06:37.000000', NULL, 1),
(6148058, 906185, 23394, '<td valign="top">great idea, nice enough shot!  personally, i prefer a lower perspective (like floor low), to get more dramatic and dynamic images.</td>', 'great idea, nice enough shot!  personally, i prefer a lower perspective (like floor low), to get more dramatic and dynamic images.', '2010-09-01 09:08:05.000000', NULL, 1),
(6148061, 906725, 23394, '<td valign="top">nice enough shot, but nothing pj about it.  sure, there are plenty of assignments that say ''go get a shot of a xxx'', but the best images are the ones that make other photojournalist say, ''i wish i''d shot that''</td>', 'nice enough shot, but nothing pj about it.  sure, there are plenty of assignments that say ''go get a shot of a xxx'', but the best images are the ones that make other photojournalist say, ''i wish i''d shot that''', '2010-09-01 09:10:15.000000', NULL, 1),
(6148065, 906019, 23394, '<td valign="top">great shot, best i''ve seen so far.  don''t know what ''wather'' is, though...</td>', 'great shot, best i''ve seen so far.  don''t know what ''wather'' is, though...', '2010-09-01 09:10:52.000000', NULL, 1),
(6148070, 906706, 23394, '<td valign="top">nah.  this is a caption looking for a photo, rather than a story-telling photo that needs no caption...</td>', 'nah.  this is a caption looking for a photo, rather than a story-telling photo that needs no caption...', '2010-09-01 09:11:48.000000', NULL, 1),
(6148072, 906029, 33361, '<td valign="top">I wish you could crop of the top - the rest of the image is AWESOME!</td>', 'I wish you could crop of the top - the rest of the image is AWESOME!', '2010-09-01 09:12:17.000000', NULL, 1),
(6148073, 906565, 23394, '<td valign="top">excellent.  one of the best i''ve seen so far.</td>', 'excellent.  one of the best i''ve seen so far.', '2010-09-01 09:12:20.000000', NULL, 1),
(6148076, 905751, 33361, '<td valign="top">Nice catch (pun intended!).</td>', 'Nice catch (pun intended!).', '2010-09-01 09:12:53.000000', NULL, 1),
