(6148249, 906881, 118396, '<td valign="top">Absolutely gorgeous pup, but I''m not sure I''d consider the classifieds as photojournalism.</td>', 'Absolutely gorgeous pup, but I''m not sure I''d consider the classifieds as photojournalism.', '2010-09-01 10:34:24.000000', NULL, 1),
(6148254, 905635, 118396, '<td valign="top">I love this photo - it''s beautiful.  I personally can''t make the connection to photojournalism.  :(</td>', 'I love this photo - it''s beautiful.  I personally can''t make the connection to photojournalism.  :(', '2010-09-01 10:38:33.000000', NULL, 1),
