(6148333, 905809, 57460, '<td valign="top">Wow, nice catch, right place right time?  The photo is a little overexposed though.  But nice catch!</td>', 'Wow, nice catch, right place right time?  The photo is a little overexposed though.  But nice catch!', '2010-09-01 11:18:13.000000', NULL, 1),
(6148336, 906029, 3102, '<td valign="top">If that''s the headline, I would have wanted to see a bit more of the polar bear :)  Otherwise, an excellent shot, and a good representation for the challenge, though!</td>', 'If that''s the headline, I would have wanted to see a bit more of the polar bear :)  Otherwise, an excellent shot, and a good representation for the challenge, though!', '2010-09-01 11:20:48.000000', NULL, 1),
(6148338, 906019, 3102, '<td valign="top">Finally... a shot that meets the challenge, and meets it well!  Very impressive -- nicely done.</td>', 'Finally... a shot that meets the challenge, and meets it well!  Very impressive -- nicely done.', '2010-09-01 11:22:12.000000', NULL, 1),
(6148340, 906512, 3102, '<td valign="top">I love Huey!  I have seen him many, many times in concert, but not for a few years now.  I had a chance to meet him back around 1990... one of the nicest musicians I''ve ever met.<br/> <br/>Anyway... nice shot -- could have been just a tad better focused, but that''s easier said than done in this environment :)</td>', 'I love Huey!  I have seen him many, many times in concert, but not for a few years now.  I had a chance to meet him back around 1990... one of the nicest musicians I''ve ever met. Anyway... nice shot -- could have been just a tad better focused, but that''s easier said than done in this environment :)', '2010-09-01 11:24:27.000000', NULL, 1),
(6148414, 906056, 23394, '<td valign="top">vacation snapshot, not front page material</td>', 'vacation snapshot, not front page material', '2010-09-01 12:34:14.000000', NULL, 1),
(6148417, 906584, 23394, '<td valign="top">nice environmental portrait, but there''s no story here.  pj images are most effective when they need no caption to tell the who-what-when-where-why.</td>', 'nice environmental portrait, but there''s no story here.  pj images are most effective when they need no caption to tell the who-what-when-where-why.', '2010-09-01 12:35:19.000000', NULL, 1),
(6148419, 905809, 23394, '<td valign="top">this is about as close as you can get and about as good as you can do under minimal editing.  nice work!</td>', 'this is about as close as you can get and about as good as you can do under minimal editing.  nice work!', '2010-09-01 12:36:07.000000', NULL, 1),
(6148421, 906345, 23394, '<td valign="top">nah.  dnmc.  nothing pj about it.</td>', 'nah.  dnmc.  nothing pj about it.', '2010-09-01 12:36:52.000000', NULL, 1),
(6148422, 906576, 23394, '<td valign="top">sorry, but it would have to be a slow news day to put this on the cover of a mag or the front page of a newspaper...</td>', 'sorry, but it would have to be a slow news day to put this on the cover of a mag or the front page of a newspaper...', '2010-09-01 12:37:30.000000', NULL, 1),
(6148423, 906840, 23394, '<td valign="top">nice illustration, but not really front page material.</td>', 'nice illustration, but not really front page material.', '2010-09-01 12:37:52.000000', NULL, 1),
(6148424, 905609, 23394, '<td valign="top">not really front page material here.  for a pj image to be effective, it needs some story-telling elements that can explain  who-what-when-where-why without relying on a caption.</td>', 'not really front page material here.  for a pj image to be effective, it needs some story-telling elements that can explain  who-what-when-where-why without relying on a caption.', '2010-09-01 12:38:57.000000', NULL, 1),
(6148431, 906512, 23394, '<td valign="top">did he die?  did he collapse on stage?  what''s the front page story behind this photo that would make it front page worthy?  a good pj shot needs some story-telling elements.</td>', 'did he die?  did he collapse on stage?  what''s the front page story behind this photo that would make it front page worthy?  a good pj shot needs some story-telling elements.', '2010-09-01 12:40:46.000000', NULL, 1),
(6148433, 906677, 23394, '<td valign="top">nice shot!</td>', 'nice shot!', '2010-09-01 12:41:06.000000', NULL, 1),
(6148436, 906028, 23394, '<td valign="top">nice work.  it immediately grabbed my attention!  hope this does well, as it''s one of the few that meets the challenge dead on.</td>', 'nice work.  it immediately grabbed my attention!  hope this does well, as it''s one of the few that meets the challenge dead on.', '2010-09-01 12:42:32.000000', NULL, 1),
(6148438, 906029, 103142, '<td valign="top">not voting yet, but this is a great capture and a perfect photojournalism subject. Nicely done.</td>', 'not voting yet, but this is a great capture and a perfect photojournalism subject. Nicely done.', '2010-09-01 12:42:49.000000', NULL, 1),
(6148440, 906755, 23394, '<td valign="top">i get what you''re after from the caption, not from the image.  a good pj image needs the story-telling elements in the image.</td>', 'i get what you''re after from the caption, not from the image.  a good pj image needs the story-telling elements in the image.', '2010-09-01 12:43:35.000000', NULL, 1),
(6148443, 906423, 23394, '<td valign="top">without seeing the hint of the microphone, i''d have no clue as to what was going on here.  not enough story telling elements to give me any sense of who-what-when-where-why; don''t think this would make the front page.</td>', 'without seeing the hint of the microphone, i''d have no clue as to what was going on here.  not enough story telling elements to give me any sense of who-what-when-where-why; don''t think this would make the front page.', '2010-09-01 12:44:53.000000', NULL, 1),
