(6153748, 906699, 28322, '<td valign="top">Yepppppp .. Photojournalism :) 10 from me,</td>', 'Yepppppp .. Photojournalism :) 10 from me,', '2010-09-06 17:33:41.000000', NULL, 1),
(6153785, 906677, 70270, '<td valign="top">great timing.  I''d have cropped closer and lost the SS, but still sports page worthy</td>', 'great timing.  I''d have cropped closer and lost the SS, but still sports page worthy', '2010-09-06 18:18:08.000000', NULL, 1),
(6154082, 906158, 114450, '<td valign="top">looks too fake.</td>', 'looks too fake.', '2010-09-07 00:19:49.000000', NULL, 1),
(6154087, 906689, 120675, '<td valign="top">Next day''s headline: "Malthouse to coach Bombers"</td>', 'Next day''s headline: "Malthouse to coach Bombers"', '2010-09-07 00:39:46.000000', NULL, 1),
(6154089, 906028, 120675, '<td valign="top">ouch!</td>', 'ouch!', '2010-09-07 00:40:31.000000', NULL, 1),
(6154430, 905809, 93565, '<td valign="top">Strikes me as a bit overexposed, but you''ve captured quite the event here. Good job.</td>', 'Strikes me as a bit overexposed, but you''ve captured quite the event here. Good job.', '2010-09-07 09:23:01.000000', NULL, 1),
(6154432, 905576, 93565, '<td valign="top">I''d like a bit more lighting on the eyes, since this appears to be a posed portrait. I''m alright with the contrasty scene, but the eyes are a natural focal point for the viewer.</td>', 'I''d like a bit more lighting on the eyes, since this appears to be a posed portrait. I''m alright with the contrasty scene, but the eyes are a natural focal point for the viewer.', '2010-09-07 09:26:39.000000', NULL, 1),
(6154618, 906158, 3746, '<td valign="top">Far too contrived. Not  enough spontaneity for this challenge IMHO. Looks like a healthy middle-class girl with a bit of makeup. Technically nice though.</td>', 'Far too contrived. Not  enough spontaneity for this challenge IMHO. Looks like a healthy middle-class girl with a bit of makeup. Technically nice though.', '2010-09-07 12:30:03.000000', NULL, 1),
(6154621, 906029, 3746, '<td valign="top">Fantastico!!</td>', 'Fantastico!!', '2010-09-07 12:31:18.000000', NULL, 1),
(6154675, 906029, 120769, '<td valign="top">needs to show more of the polar bear</td>', 'needs to show more of the polar bear', '2010-09-07 13:09:47.000000', NULL, 1),
(6154678, 906881, 120769, '<td valign="top">everyone loves a good puppy</td>', 'everyone loves a good puppy', '2010-09-07 13:10:52.000000', NULL, 1),
